static vector<int> parseIntArray(const string& line) {
    vector<int> out;
    string num;
    for (char c : line) {
        if (c == '-' || isdigit(static_cast<unsigned char>(c))) {
            num += c;
        } else if (!num.empty()) {
            out.push_back(stoi(num));
            num.clear();
        }
    }
    if (!num.empty()) out.push_back(stoi(num));
    return out;
}

